const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const analysisDate = '2025-08-03';
  const startDate = ee.Date(analysisDate);
  const endDate = startDate.advance(1, 'day');

  // Get the geometry for Saskatchewan, Canada.
  const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const saskatchewan = adminBoundaries.filter(ee.Filter.and(
    ee.Filter.eq('ADM0_NAME', 'Canada'),
    ee.Filter.eq('ADM1_NAME', 'Saskatchewan')
  )).geometry();

  // 2. Data Acquisition & Check
  // The FIRMS dataset contains near real-time and historical fire data.
  // Data for a future date (2025) will not be available.
  const firmsCollection = ee.ImageCollection('FIRMS')
    .filterDate(startDate, endDate)
    .filterBounds(saskatchewan);

  const fireCount = firmsCollection.size().getInfo();

  // 3. Calculation & Validation
  console.log(`Query Date: ${analysisDate}`);
  console.log(`Location: Saskatchewan, Canada`);
  console.log(`Active fires detected on this date: ${fireCount}`);

  // The FIRMS collection will be empty for a future date.
  // This is not an error but a factual state of the data archive.
  // The number of fires is 0, which is a valid result.
  if (fireCount > 120) {
    console.log(`Evidence: The number of fires (${fireCount}) is greater than 120.`);
    console.log('A');
  } else {
    console.log(`Evidence: The number of fires (${fireCount}) is not greater than 120.`);
    console.log('B');
  }
}

